practice.solutionCode:
// Day 1: 개발 환경과 첫 출력 예시 풀이
#include <stdio.h>

int main(void) {
    int values[] = {1, 2, 3, 4};
    int total = 0;
    for (int i = 0; i < 4; i++) {
        total += values[i];
    }
    printf("개발 환경과 첫 출력: %d\n", total);
    return 0;
}

